#!/usr/bin/env python3
"""Deterministic additive guest-command wrappers; no other generated files."""
import argparse,hashlib,json
from copy import deepcopy
from check_contracts import Validator,variant_coverage
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
NAMES=('guest_command_request','guest_command_event','guest_command_session','guest_transport_metadata')
HEADER='''//! Additive guest command wrappers; generated by tools/generate_guest_command_contracts.py.
use serde::{Deserialize, Deserializer, Serialize};
use serde_json::Value;
macro_rules! message {
    ($name:ident, $schema:literal) => {
        #[derive(Clone, Debug, PartialEq, Eq, Serialize)]
        #[serde(transparent)]
        pub struct $name(pub Value);
        impl<'de> Deserialize<'de> for $name {
            fn deserialize<D: Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
                let value = Value::deserialize(d)?;
                let schema = super::schemas::schema(concat!($schema, ".schema.json"))
                    .ok_or_else(|| serde::de::Error::custom("missing guest command schema"))?;
                if !super::valid(&value, &schema, &schema) {
                    return Err(serde::de::Error::custom("invalid guest command contract"));
                }
                Ok(Self(value))
            }
        }
    };
}
message!(GuestCommandRequest, "guest_command_request");
message!(GuestCommandEvent, "guest_command_event");
message!(GuestCommandSession, "guest_command_session");
message!(GuestTransportMetadata, "guest_transport_metadata");
'''
def fixture_variants(node,root,validator):
 if '$ref' in node:
  target,targetroot=validator.resolve(node['$ref'],root);return fixture_variants(target,targetroot,validator)
 if 'const' in node:return [node['const']]
 if 'enum' in node:return node['enum']
 if 'oneOf' in node:return [v for branch in node['oneOf'] for v in fixture_variants(branch,root,validator)]
 typ=node.get('type')
 if typ=='object':
  fields={key:fixture_variants(child,root,validator) for key,child in node['properties'].items()}
  base={key:values[0] for key,values in fields.items()};out=[base]
  for key,values in fields.items():
   for value in values[1:]:out.append({**base,key:value})
  return out
 if typ=='null':return [None]
 if typ=='boolean':return [False,True]
 if typ=='integer':return [node.get('minimum',0)]
 if typ=='string':
  pattern=node.get('pattern','')
  for prefix in ('workload','request','job','event','actor','reservation'):
   if pattern.startswith('^'+prefix+'-'):return [prefix+'-fixture']
  if pattern=='^[0-9a-f]{64}$':return ['a'*64]
  if 'A-Za-z0-9+/' in pattern:return ['YQ==' if node.get('minLength',0) else '']
  return ['x'*node.get('minLength',0)]
 raise ValueError(node)
def fixtures(check=False):
 validator=Validator(ROOT/'contracts/v0.2');directory=ROOT/'contracts/examples/v0.2'
 for name in NAMES:
  schema=validator.load(name+'.schema.json');validator.audit(schema)
  candidates=fixture_variants(schema,schema,validator);chosen=[];missing=set(variant_coverage(validator,schema,[]))
  candidates=[(value,missing-set(variant_coverage(validator,schema,[value]))) for value in candidates]
  while missing:
   best,coverage=max(candidates,key=lambda item:len(item[1]&missing))
   if not coverage&missing:raise ValueError('fixture coverage cannot progress')
   chosen.append(best);missing-=coverage
  if not chosen:chosen=[candidates[0][0]]
  for index,value in enumerate(chosen):
   path=directory/(name+'.valid.generated'+str(index)+'.json');text=json.dumps(value,indent=2)+'\n'
   if check:
    if path.read_text()!=text:raise ValueError('fixture drift')
   else:path.write_text(text)
def envelope_fixtures(check=False):
 directory=ROOT/'contracts/examples/v0.2'
 for family in ('guest_command_request','guest_command_event'):
  for index,path in enumerate(sorted(directory.glob(family+'.valid*.json'))):
   value={'schema':'capsule_envelope/v0.2','msg_id':'guest-command-fixture','ts_ns':0,'from':{'component':'ui' if family.endswith('request') else 'core','instance':'fixture-from'},'to':{'component':'core' if family.endswith('request') else 'agent','instance':'fixture-to'},'session_id':'fixture-session','seq':1,'nonce':'fixture-nonce','body':json.loads(path.read_text())}
   target=directory/('capsule_envelope.valid.'+family+'.'+str(index)+'.json');text=json.dumps(value,indent=2)+'\n'
   if check:
    if target.read_text()!=text:raise ValueError('envelope fixture drift')
   else:target.write_text(text)
def main():
 p=argparse.ArgumentParser();p.add_argument('--check',action='store_true');p.add_argument('--examples',action='store_true');a=p.parse_args()
 content=HEADER+''.join('// '+n+' SHA256 '+hashlib.sha256((ROOT/'contracts/v0.2'/f'{n}.schema.json').read_bytes()).hexdigest()+'\n'for n in NAMES)
 target=ROOT/'core/src/wire/guest_command.rs'
 if a.check:
  if target.read_text()!=content:raise SystemExit('guest-command wrappers stale')
 else:target.write_text(content)
 if a.examples:
  fixtures(a.check);envelope_fixtures(a.check)
if __name__=='__main__':main()
